#!/bin/zsh
# Step 8 / H-4: X-video walk clip from the H1 E rest frame r2 via the Grok subscription CLI (headless; T30 done). Conductor-driven; zero Astra images.
set -e
B=/Users/admin/Games/reincarnated-collaboration/astra_test_01/burst
STILL="$B/runs/C-1/artifacts/K2p-gen-E-r2/k2p_E_r2.png"
OUTDIR="$B/runs/C-1/xvideo/in"; mkdir -p "$OUTDIR"; WORK="$HOME/astra-burst/grok/walk_E"; mkdir -p "$WORK"
PROMPT='The character walks in place in full right-facing profile — she faces screen-right and keeps facing screen-right for the whole clip — on a flat solid pure green (#00ff00) background that stays completely unchanged and empty (no scenery, no shadows, no particles). Camera locked, no zoom, no pan; the figure stays centred at the same size. A natural, confident, weighty walk cycle in place: the feet lift and plant clearly, the planted foot sliding back under the body like a treadmill; the head bobs down into each footfall and rises through the passing position, about twice per stride; the free near arm swings opposite the legs; the far arm holds the staff upright and swings only a little; the head and gaze stay level, looking ahead along the path, never turning to the camera. Same face, same hair, same costume, same colours, same staff and satchel in every frame. Hand-drawn 2D animation, one continuous shot, no cuts. Loop: the last frame matches the first.'
cd "$WORK"
~/.grok/bin/grok -p "Use your image_to_video tool ONCE with these exact arguments: image = $STILL (this still is the FIRST frame), prompt = \"$PROMPT\", duration = 6, resolution = 720p. When it returns, save/copy the resulting MP4 into the current directory as walk_E_grok.mp4 (download it if the tool returns a URL), then print exactly one line: SAVED <absolute path> <size in bytes> <costUSD if reported>. Do nothing else; do not edit the image; do not generate a second video." --always-approve 2>&1 | tail -15
ls -la "$WORK"; f=$(ls "$WORK"/*.mp4 2>/dev/null | head -1); [ -n "$f" ] && cp "$f" "$OUTDIR/walk_E_grok.mp4" && echo "COPIED → $OUTDIR/walk_E_grok.mp4 ($(stat -f %z "$OUTDIR/walk_E_grok.mp4") bytes)" && /opt/homebrew/bin/ffprobe -v error -select_streams v:0 -show_entries stream=width,height,r_frame_rate,nb_frames,duration -of default=nw=1 "$OUTDIR/walk_E_grok.mp4"
